export enum AppTab {
  TTS = 'TTS',
  STT = 'STT'
}

export enum VoiceName {
  Puck = 'Puck',
  Charon = 'Charon',
  Kore = 'Kore',
  Fenrir = 'Fenrir',
  Zephyr = 'Zephyr'
}

export interface AudioConfig {
  voiceName: VoiceName;
}

export interface TranscribeResult {
  text: string;
}

// Helper type for the PCM decoder
export interface PcmAudioBuffer {
  data: Float32Array;
  sampleRate: number;
}

/**
 * Decodes a base64 string into a Uint8Array of bytes.
 */
export function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

/**
 * Decodes raw PCM audio data (from Gemini TTS) into an AudioBuffer.
 * Gemini TTS typically returns raw PCM 16-bit mono at 24kHz.
 */
export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1,
): Promise<AudioBuffer> {
  // Convert Uint8Array (bytes) to Int16Array
  const dataInt16 = new Int16Array(data.buffer);

  // Create an AudioBuffer
  const buffer = ctx.createBuffer(numChannels, dataInt16.length, sampleRate);

  // Fill the buffer with float data converted from Int16
  const channelData = buffer.getChannelData(0); // Mono
  for (let i = 0; i < dataInt16.length; i++) {
    // Convert 16-bit integer (-32768 to 32767) to float (-1.0 to 1.0)
    channelData[i] = dataInt16[i] / 32768.0;
  }

  return buffer;
}

/**
 * Converts a Blob to a Base64 string.
 */
export function blobToBase64(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      // Remove the Data URL prefix (e.g., "data:audio/wav;base64,")
      const base64 = base64String.split(',')[1];
      resolve(base64);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

import { GoogleGenAI, Modality } from "@google/genai";
import { VoiceName } from "../types";

// Initialize the client with the API key from environment variables
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates speech from text using the gemini-2.5-flash-preview-tts model.
 * Returns the raw base64 encoded PCM audio data.
 */
export const generateSpeech = async (text: string, voice: VoiceName): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) {
      throw new Error("No audio data returned from the model.");
    }

    return base64Audio;
  } catch (error) {
    console.error("Error generating speech:", error);
    throw error;
  }
};

/**
 * Transcribes audio using the gemini-3-flash-preview model.
 */
export const transcribeAudio = async (base64Audio: string, mimeType: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Audio,
            },
          },
          {
            text: "Transcribe the audio exactly as spoken.",
          },
        ],
      },
    });

    const text = response.text;
    if (!text) {
      throw new Error("No transcription text returned.");
    }
    return text;
  } catch (error) {
    console.error("Error transcribing audio:", error);
    throw error;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { VoiceName } from '../types';
import { generateSpeech } from '../services/geminiService';
import { decode, decodeAudioData } from '../utils/audio';
import { Play, Square, Loader2, Sparkles, Wand2 } from 'lucide-react';

const TextToSpeech: React.FC = () => {
  const [text, setText] = useState<string>("Hello! Welcome to Magic Voice Development. I can turn any text into realistic speech.");
  const [selectedVoice, setSelectedVoice] = useState<VoiceName>(VoiceName.Kore);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    // Initialize AudioContext
    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
      audioContextRef.current = new AudioContextClass({ sampleRate: 24000 });
    }

    return () => {
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
    };
  }, []);

  const handleGenerateAndPlay = async () => {
    if (!text.trim()) return;
    setIsLoading(true);
    setError(null);
    stopAudio(); // Stop any currently playing audio

    try {
      const base64Audio = await generateSpeech(text, selectedVoice);

      if (!audioContextRef.current) {
        throw new Error("AudioContext not supported in this browser");
      }

      // Resume context if suspended (browser autoplay policy)
      if (audioContextRef.current.state === 'suspended') {
        await audioContextRef.current.resume();
      }

      const audioBytes = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioBytes, audioContextRef.current, 24000, 1);

      playBuffer(audioBuffer);

    } catch (err: any) {
      console.error(err);
      setError(err.message || "Failed to generate speech. Please check your API key.");
    } finally {
      setIsLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    if (!audioContextRef.current) return;

    const source = audioContextRef.current.createBufferSource();
    source.buffer = buffer;
    source.connect(audioContextRef.current.destination);

    source.onended = () => {
      setIsPlaying(false);
      sourceNodeRef.current = null;
    };

    sourceNodeRef.current = source;
    source.start();
    setIsPlaying(true);
  };

  const stopAudio = () => {
    if (sourceNodeRef.current) {
      sourceNodeRef.current.stop();
      sourceNodeRef.current = null;
    }
    setIsPlaying(false);
  };

  return (
    <div className="w-full max-w-4xl mx-auto p-6">
      <div className="bg-slate-900/50 backdrop-blur-md rounded-2xl border border-slate-700/50 p-6 md:p-8 shadow-2xl">
        <div className="flex items-center gap-3 mb-6">
          <div className="p-3 bg-indigo-600 rounded-lg shadow-lg shadow-indigo-600/20">
            <Wand2 className="w-6 h-6 text-white" />
          </div>
          <h2 className="text-2xl font-bold text-white">Text to Magic Voice</h2>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* Main Input Area */}
          <div className="md:col-span-2 space-y-4">
            <label className="block text-sm font-medium text-slate-300">
              Enter your text
            </label>
            <textarea
              className="w-full h-48 bg-slate-800/50 border border-slate-600 rounded-xl p-4 text-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition resize-none"
              placeholder="Type something amazing here..."
              value={text}
              onChange={(e) => setText(e.target.value)}
            />
            {error && (
              <div className="p-3 bg-red-900/30 border border-red-800 rounded-lg text-red-200 text-sm">
                {error}
              </div>
            )}
          </div>

          {/* Controls */}
          <div className="space-y-6">
            <div className="space-y-2">
              <label className="block text-sm font-medium text-slate-300">
                Select Voice
              </label>
              <div className="grid grid-cols-1 gap-2">
                {Object.values(VoiceName).map((voice) => (
                  <button
                    key={voice}
                    onClick={() => setSelectedVoice(voice)}
                    className={`flex items-center justify-between px-4 py-3 rounded-xl border transition-all ${
                      selectedVoice === voice
                        ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg shadow-indigo-900/20'
                        : 'bg-slate-800/50 border-slate-700 text-slate-300 hover:bg-slate-700/50 hover:border-slate-600'
                    }`}
                  >
                    <span className="font-medium">{voice}</span>
                    {selectedVoice === voice && <Sparkles className="w-4 h-4 text-indigo-200" />}
                  </button>
                ))}
              </div>
            </div>

            <div className="pt-4">
              {!isPlaying ? (
                <button
                  onClick={handleGenerateAndPlay}
                  disabled={isLoading || !text}
                  className="w-full py-4 bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-400 hover:to-purple-500 text-white font-bold rounded-xl shadow-lg shadow-indigo-900/30 disabled:opacity-50 disabled:cursor-not-allowed transition-all transform hover:scale-[1.02] active:scale-[0.98] flex items-center justify-center gap-2"
                >
                  {isLoading ? (
                    <>
                      <Loader2 className="w-5 h-5 animate-spin" />
                      <span>Generating...</span>
                    </>
                  ) : (
                    <>
                      <Play className="w-5 h-5 fill-current" />
                      <span>Generate & Play</span>
                    </>
                  )}
                </button>
              ) : (
                <button
                  onClick={stopAudio}
                  className="w-full py-4 bg-red-500 hover:bg-red-400 text-white font-bold rounded-xl shadow-lg shadow-red-900/30 transition-all transform hover:scale-[1.02] active:scale-[0.98] flex items-center justify-center gap-2"
                >
                  <Square className="w-5 h-5 fill-current" />
                  <span>Stop Audio</span>
                </button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TextToSpeech;

import React, { useState, useRef } from 'react';
import { transcribeAudio } from '../services/geminiService';
import { blobToBase64 } from '../utils/audio';
import { Mic, Square, Loader2, FileText, Upload } from 'lucide-react';

const SpeechToText: React.FC = () => {
  const [transcription, setTranscription] = useState<string>("");
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorderRef.current = new MediaRecorder(stream);
      chunksRef.current = [];

      mediaRecorderRef.current.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunksRef.current.push(e.data);
        }
      };

      mediaRecorderRef.current.onstop = async () => {
        const blob = new Blob(chunksRef.current, { type: 'audio/webm' });
        await handleTranscription(blob, 'audio/webm');

        // Stop all tracks
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorderRef.current.start();
      setIsRecording(true);
      setError(null);
    } catch (err) {
      console.error("Error accessing microphone:", err);
      setError("Could not access microphone. Please check permissions.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('audio/')) {
      setError("Please upload a valid audio file.");
      return;
    }

    await handleTranscription(file, file.type);
  };

  const handleTranscription = async (blob: Blob, mimeType: string) => {
    setIsProcessing(true);
    setError(null);

    try {
      const base64Audio = await blobToBase64(blob);
      const result = await transcribeAudio(base64Audio, mimeType);
      setTranscription(result);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Failed to transcribe audio.");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="w-full max-w-4xl mx-auto p-6">
      <div className="bg-slate-900/50 backdrop-blur-md rounded-2xl border border-slate-700/50 p-6 md:p-8 shadow-2xl">
        <div className="flex items-center gap-3 mb-6">
          <div className="p-3 bg-purple-600 rounded-lg shadow-lg shadow-purple-600/20">
            <Mic className="w-6 h-6 text-white" />
          </div>
          <h2 className="text-2xl font-bold text-white">Magic Audio Transcription</h2>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* Controls Area */}
          <div className="space-y-6">
            <div className="bg-slate-800/50 rounded-xl p-4 border border-slate-700">
              <h3 className="text-sm font-medium text-slate-300 mb-4">Record Audio</h3>
              {!isRecording ? (
                <button
                  onClick={startRecording}
                  disabled={isProcessing}
                  className="w-full py-8 bg-slate-700 hover:bg-slate-600 border-2 border-dashed border-slate-500 rounded-xl transition-all flex flex-col items-center justify-center gap-3 group"
                >
                  <div className="p-4 bg-purple-600 rounded-full group-hover:scale-110 transition-transform shadow-lg shadow-purple-900/50">
                    <Mic className="w-8 h-8 text-white" />
                  </div>
                  <span className="text-slate-300 font-medium">Click to Record</span>
                </button>
              ) : (
                <button
                  onClick={stopRecording}
                  className="w-full py-8 bg-red-900/20 hover:bg-red-900/30 border-2 border-red-500 rounded-xl transition-all flex flex-col items-center justify-center gap-3 animate-pulse"
                >
                  <div className="p-4 bg-red-500 rounded-full shadow-lg shadow-red-900/50">
                    <Square className="w-8 h-8 text-white fill-current" />
                  </div>
                  <span className="text-red-300 font-medium">Recording... (Click to Stop)</span>
                </button>
              )}
            </div>

            <div className="relative">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-slate-700"></div>
              </div>
              <div className="relative flex justify-center text-sm">
                <span className="px-2 bg-slate-900 text-slate-400">Or upload file</span>
              </div>
            </div>

            <label className="block w-full cursor-pointer">
              <input 
                type="file" 
                accept="audio/*" 
                className="hidden" 
                onChange={handleFileUpload}
                disabled={isProcessing || isRecording}
              />
              <div className="w-full py-3 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl border border-slate-600 transition-colors flex items-center justify-center gap-2">
                <Upload className="w-4 h-4" />
                <span>Upload Audio File</span>
              </div>
            </label>
          </div>

          {/* Result Area */}
          <div className="md:col-span-2 flex flex-col h-full">
            <div className="flex items-center justify-between mb-2">
              <label className="text-sm font-medium text-slate-300">
                Transcription Result
              </label>
              {isProcessing && (
                <span className="flex items-center gap-2 text-indigo-400 text-sm animate-pulse">
                  <Loader2 className="w-3 h-3 animate-spin" />
                  Processing audio with Gemini...
                </span>
              )}
            </div>

            <div className="relative flex-grow min-h-[300px] bg-slate-800/50 border border-slate-600 rounded-xl p-4">
              {transcription ? (
                <div className="prose prose-invert max-w-none text-slate-200 whitespace-pre-wrap">
                  {transcription}
                </div>
              ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-500 opacity-50">
                  <FileText className="w-12 h-12 mb-2" />
                  <p>Transcribed text will appear here</p>
                </div>
              )}

              {error && (
                <div className="absolute inset-x-4 bottom-4 p-3 bg-red-900/80 border border-red-800 backdrop-blur rounded-lg text-red-200 text-sm">
                  {error}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SpeechToText;

