import React, { useState, useRef, useEffect } from 'react';
import { VoiceName, SpeakingTone } from '../types';
import { generateSpeech } from '../services/geminiService';
import { decode, decodeAudioData } from '../utils/audio';
import { Play, Square, Loader2, Sparkles, Wand2 } from 'lucide-react';

const TextToSpeech: React.FC = () => {
  const [text, setText] = useState<string>("Hello! Welcome to Magic Voice Development. I can turn any text into realistic speech.");
  const [selectedVoice, setSelectedVoice] = useState<VoiceName>(VoiceName.Kore);
  const [selectedTone, setSelectedTone] = useState<SpeakingTone>(SpeakingTone.Normal);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    // Initialize AudioContext
    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
      audioContextRef.current = new AudioContextClass({ sampleRate: 24000 });
    }

    return () => {
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
    };
  }, []);

  const handleGenerateAndPlay = async () => {
    if (!text.trim()) return;
    setIsLoading(true);
    setError(null);
    stopAudio();

    try {
      // Small optimization: Prepend tone to text if it's not Normal, 
      // though gemini-2.5-flash-tts works best with direct text, sometimes context helps.
      // For pure TTS, we send the text.

      const base64Audio = await generateSpeech(text, selectedVoice);

      if (!audioContextRef.current) {
        throw new Error("AudioContext not supported in this browser");
      }

      if (audioContextRef.current.state === 'suspended') {
        await audioContextRef.current.resume();
      }

      const audioBytes = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioBytes, audioContextRef.current, 24000, 1);

      playBuffer(audioBuffer);

    } catch (err: any) {
      console.error(err);
      setError(err.message || "Failed to generate speech.");
    } finally {
      setIsLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    if (!audioContextRef.current) return;

    const source = audioContextRef.current.createBufferSource();
    source.buffer = buffer;
    source.connect(audioContextRef.current.destination);

    source.onended = () => {
      setIsPlaying(false);
      sourceNodeRef.current = null;
    };

    sourceNodeRef.current = source;
    source.start();
    setIsPlaying(true);
  };

  const stopAudio = () => {
    if (sourceNodeRef.current) {
      sourceNodeRef.current.stop();
      sourceNodeRef.current = null;
    }
    setIsPlaying(false);
  };

  return (
    <div className="w-full max-w-5xl mx-auto">
      <div className="bg-slate-900/50 backdrop-blur-md rounded-2xl border border-slate-700/50 p-6 md:p-8 shadow-2xl">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Main Input Area */}
          <div className="lg:col-span-2 space-y-4">
            <div className="flex justify-between items-center">
                <label className="block text-sm font-medium text-slate-300">
                  Enter your text
                </label>
                <div className="text-xs text-slate-500">
                    Characters: {text.length}
                </div>
            </div>
            <textarea
              className="w-full h-64 bg-slate-800/50 border border-slate-600 rounded-xl p-4 text-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition resize-none font-light leading-relaxed text-lg"
              placeholder="Type something amazing here..."
              value={text}
              onChange={(e) => setText(e.target.value)}
            />
            {error && (
              <div className="p-3 bg-red-900/30 border border-red-800 rounded-lg text-red-200 text-sm">
                {error}
              </div>
            )}
          </div>

          {/* Controls */}
          <div className="space-y-6">

            <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-700 space-y-4">
                <div className="space-y-2">
                    <label className="block text-sm font-medium text-slate-300">
                        Speaking Style (Tone)
                    </label>
                    <select 
                        value={selectedTone}
                        onChange={(e) => setSelectedTone(e.target.value as SpeakingTone)}
                        className="w-full bg-slate-900 border border-slate-600 rounded-lg px-3 py-2 text-white focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    >
                        {Object.values(SpeakingTone).map((tone) => (
                            <option key={tone} value={tone}>{tone}</option>
                        ))}
                    </select>
                    <p className="text-xs text-slate-500">
                        *Tone applies heavily to generated content. For direct TTS, phrasing matters more.
                    </p>
                </div>

                <div className="space-y-2 pt-2">
                    <label className="block text-sm font-medium text-slate-300">
                        Select Voice
                    </label>
                    <div className="grid grid-cols-1 gap-2 max-h-48 overflow-y-auto pr-1 custom-scrollbar">
                        {Object.values(VoiceName).map((voice) => (
                        <button
                            key={voice}
                            onClick={() => setSelectedVoice(voice)}
                            className={`flex items-center justify-between px-3 py-2.5 rounded-lg border transition-all text-sm ${
                            selectedVoice === voice
                                ? 'bg-indigo-600 border-indigo-500 text-white'
                                : 'bg-slate-900 border-slate-700 text-slate-300 hover:border-slate-500'
                            }`}
                        >
                            <span className="font-medium">{voice}</span>
                            {selectedVoice === voice && <Sparkles className="w-3 h-3 text-indigo-200" />}
                        </button>
                        ))}
                    </div>
                </div>
            </div>

            <div className="pt-2">
              {!isPlaying ? (
                <button
                  onClick={handleGenerateAndPlay}
                  disabled={isLoading || !text}
                  className="w-full py-4 bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-400 hover:to-purple-500 text-white font-bold rounded-xl shadow-lg shadow-indigo-900/30 disabled:opacity-50 disabled:cursor-not-allowed transition-all transform hover:scale-[1.02] active:scale-[0.98] flex items-center justify-center gap-2"
                >
                  {isLoading ? (
                    <>
                      <Loader2 className="w-5 h-5 animate-spin" />
                      <span>Generating...</span>
                    </>
                  ) : (
                    <>
                      <Play className="w-5 h-5 fill-current" />
                      <span>Generate Voice</span>
                    </>
                  )}
                </button>
              ) : (
                <button
                  onClick={stopAudio}
                  className="w-full py-4 bg-red-500 hover:bg-red-400 text-white font-bold rounded-xl shadow-lg shadow-red-900/30 transition-all transform hover:scale-[1.02] active:scale-[0.98] flex items-center justify-center gap-2"
                >
                  <Square className="w-5 h-5 fill-current" />
                  <span>Stop Audio</span>
                </button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TextToSpeech;

