                                {Object.values(VoiceName).map(v => <option key={v} value={v}>{v}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-300 mb-2">Tone</label>
                            <select 
                                value={tone}
                                onChange={(e) => setTone(e.target.value as SpeakingTone)}
                                className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-white"
                            >
                                {Object.values(SpeakingTone).map(t => <option key={t} value={t}>{t}</option>)}
                            </select>
                        </div>
                    </div>

                    {!isPlaying ? (
                        <button
                            onClick={processImageToVoice}
                            disabled={isLoading || !selectedImage}
                            className="w-full py-4 bg-gradient-to-r from-emerald-600 to-teal-600 text-white font-bold rounded-xl shadow-lg shadow-emerald-900/30 flex items-center justify-center gap-2 hover:scale-[1.02] transition-transform disabled:opacity-50"
                        >
                            {isLoading ? <Loader2 className="animate-spin" /> : <ImageIcon />}
                            <span>Analyze & Speak</span>
                        </button>
                    ) : (
                        <button onClick={stopAudio} className="w-full py-4 bg-red-500 text-white font-bold rounded-xl flex items-center justify-center gap-2">
                            <Square className="fill-current" /> Stop Audio
                        </button>
                    )}

                    {error && <div className="text-red-400 text-sm">{error}</div>}
                </div>

                {/* Right: Result Text */}
                <div className="bg-slate-950/50 rounded-xl border border-slate-800 p-6 flex flex-col">
                    <h3 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-4">What Gemini Sees</h3>
                    {generatedText ? (
                        <div className="prose prose-invert text-lg font-light leading-relaxed">
                            "{generatedText}"
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col items-center justify-center text-slate-600 opacity-50">
                            <Loader2 className={`w-8 h-8 mb-2 ${isLoading ? 'animate-spin block' : 'hidden'}`} />
                            <p>{isLoading ? "Analyzing image..." : "Description will appear here"}</p>
                        </div>
                    )}
                </div>

            </div>
        </div>
    </div>
  );
};

