import React, { useState, useRef, useEffect } from 'react';
import { VoiceName, SpeakingTone } from '../types';
import { generateDialogue } from '../services/geminiService';
import { decode, decodeAudioData } from '../utils/audio';
import { VOICE_META } from '../utils/constants';
import { Play, Square, Loader2, MessageSquareText, User } from 'lucide-react';

const MagicDialogue: React.FC = () => {
  const [topic, setTopic] = useState<string>("");
  const [script, setScript] = useState<string>("");
  const [tone, setTone] = useState<SpeakingTone>(SpeakingTone.Normal);
  const [speaker1, setSpeaker1] = useState<VoiceName>(VoiceName.Fenrir);
  const [speaker2, setSpeaker2] = useState<VoiceName>(VoiceName.Puck);

  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
      audioContextRef.current = new AudioContextClass({ sampleRate: 24000 });
    }
    return () => audioContextRef.current?.close();
  }, []);

  const handleCreateDialogue = async () => {
    if (!topic.trim()) return;
    setIsLoading(true);
    setError(null);
    stopAudio();
    setScript("");

    try {
      const { audio: base64Audio, script: generatedScript } = await generateDialogue(topic, tone, speaker1, speaker2);

      setScript(generatedScript);

      if (!audioContextRef.current) throw new Error("AudioContext not supported");
      if (audioContextRef.current.state === 'suspended') await audioContextRef.current.resume();

      const audioBytes = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioBytes, audioContextRef.current, 24000, 1);

      playBuffer(audioBuffer);

    } catch (err: any) {
      console.error(err);
      setError(err.message || "Failed to create dialogue.");
    } finally {
      setIsLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    if (!audioContextRef.current) return;
    const source = audioContextRef.current.createBufferSource();
    source.buffer = buffer;
    source.connect(audioContextRef.current.destination);
    source.onended = () => {
      setIsPlaying(false);
      sourceNodeRef.current = null;
    };
    sourceNodeRef.current = source;
    source.start();
    setIsPlaying(true);
  };

  const stopAudio = () => {
    if (sourceNodeRef.current) {
      sourceNodeRef.current.stop();
      sourceNodeRef.current = null;
    }
    setIsPlaying(false);
  };

  const renderSpeakerSelect = (
    label: string, 
    value: VoiceName, 
    onChange: (val: VoiceName) => void,
    colorClass: string
  ) => {
    const meta = VOICE_META[value];
    const Icon = meta.icon;

    return (
        <div className="space-y-2">
            <label className={`block text-xs font-bold uppercase tracking-wider mb-2 flex items-center gap-1 ${colorClass}`}>
                <User className="w-3 h-3" /> {label}
            </label>
            <div className="relative group">
                <select 
                    value={value}
                    onChange={(e) => onChange(e.target.value as VoiceName)}
                    className="w-full bg-slate-800 border border-slate-600 rounded-lg pl-3 pr-10 py-3 text-white appearance-none focus:ring-2 focus:ring-indigo-500 outline-none"
                >
                    {Object.values(VoiceName).map(v => (
                        <option key={v} value={v}>
                            {VOICE_META[v].label} ({VOICE_META[v].gender})
                        </option>
                    ))}
                </select>
                <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none">
                    <Icon className="w-4 h-4 text-slate-400" />
                </div>
            </div>
            <p className="text-[10px] text-slate-500">
                {meta.style}
            </p>
        </div>
    );
  };

  return (
    <div className="w-full max-w-5xl mx-auto">
        <div className="bg-slate-900/50 backdrop-blur-md rounded-2xl border border-slate-700/50 p-6 md:p-8 shadow-2xl">

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
                {/* Configuration */}
                <div className="space-y-6">
                    <div>
                        <label className="block text-sm font-medium text-slate-300 mb-2">Conversation Topic</label>
                        <textarea
                            value={topic}
                            onChange={(e) => setTopic(e.target.value)}
                            placeholder="e.g. Discussing the best pizza toppings..."
                            className="w-full h-32 bg-slate-800/50 border border-slate-600 rounded-xl p-4 text-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4 bg-slate-950/30 p-4 rounded-xl border border-slate-800">
                        {renderSpeakerSelect("Speaker 1", speaker1, setSpeaker1, "text-indigo-300")}
                        {renderSpeakerSelect("Speaker 2", speaker2, setSpeaker2, "text-purple-300")}
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-slate-300 mb-2">Conversation Tone</label>
                        <select 
                            value={tone}
                            onChange={(e) => setTone(e.target.value as SpeakingTone)}
                            className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-3 text-white focus:outline-none focus:ring-2 focus:ring-indigo-500"
                        >
                            {Object.values(SpeakingTone).map(t => <option key={t} value={t}>{t}</option>)}
                        </select>
                    </div>

                    {!isPlaying ? (
                        <button
                            onClick={handleCreateDialogue}
                            disabled={isLoading || !topic}
                            className="w-full py-4 bg-gradient-to-r from-indigo-600 to-purple-600 text-white font-bold rounded-xl shadow-lg shadow-indigo-900/30 flex items-center justify-center gap-2 hover:scale-[1.02] transition-transform disabled:opacity-50"
                        >
                            {isLoading ? <Loader2 className="animate-spin" /> : <MessageSquareText />}
                            <span>Generate Dialogue</span>
                        </button>
                    ) : (
                        <button onClick={stopAudio} className="w-full py-4 bg-red-500 text-white font-bold rounded-xl flex items-center justify-center gap-2">
                            <Square className="fill-current" /> Stop Audio
                        </button>
                    )}

                    {error && <div className="text-red-400 text-sm bg-red-900/20 p-3 rounded-lg border border-red-800">{error}</div>}
                </div>

                {/* Script Display */}
                <div className="bg-slate-950/50 rounded-xl border border-slate-800 p-6 overflow-y-auto max-h-[500px] custom-scrollbar">
                    <h3 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-4 sticky top-0 bg-slate-950/90 pb-2 backdrop-blur">Generated Script</h3>
                    {script ? (
                        <div className="space-y-4">
                            {script.split('\n').map((line, i) => {
                                if (!line.trim()) return null;
                                const isSpeaker1 = line.startsWith(speaker1);
                                return (
                                    <div key={i} className={`flex ${isSpeaker1 ? 'justify-start' : 'justify-end'}`}>
                                        <div className={`max-w-[85%] p-3 rounded-2xl text-sm ${
                                            isSpeaker1 
                                                ? 'bg-indigo-900/40 text-indigo-100 rounded-tl-none border border-indigo-500/30' 
                                                : 'bg-purple-900/40 text-purple-100 rounded-tr-none border border-purple-500/30'
                                        }`}>
                                            <div className="text-[10px] opacity-70 mb-1 font-bold">
                                                {isSpeaker1 ? speaker1 : speaker2}
                                            </div>
                                            {line.replace(`${speaker1}:`, '').replace(`${speaker2}:`, '')}
                                        </div>
                                    </div>
                                )
                            })}
                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center text-slate-600">
                            <MessageSquareText className="w-12 h-12 mb-2 opacity-20" />
                            <p>Dialogue script will appear here</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    </div>
  );
};

export default MagicDialogue;

import React, { useState, useRef, useEffect } from 'react';
import { VoiceName, SpeakingTone } from '../types';
