import { GoogleGenAI, Modality, Type } from "@google/genai";
import { VoiceName, SpeakingTone } from "../types";

// Initialize the client with the API key from environment variables
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates speech from text using the gemini-2.5-flash-preview-tts model.
 * Returns the raw base64 encoded PCM audio data.
 */
export const generateSpeech = async (text: string, voice: VoiceName): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) {
      throw new Error("No audio data returned from the model.");
    }

    return base64Audio;
  } catch (error) {
    console.error("Error generating speech:", error);
    throw error;
  }
};

/**
 * Transcribes audio using the gemini-3-flash-preview model.
 */
export const transcribeAudio = async (base64Audio: string, mimeType: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Audio,
            },
          },
          {
            text: "Transcribe the audio exactly as spoken.",
          },
        ],
      },
    });

    const text = response.text;
    if (!text) {
      throw new Error("No transcription text returned.");
    }
    return text;
  } catch (error) {
    console.error("Error transcribing audio:", error);
    throw error;
  }
};

/**
 * Generates a description/story from an image with a specific tone.
 */
export const generateTextFromImage = async (base64Image: string, mimeType: string, tone: SpeakingTone): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-image",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: `Describe what is in this image or tell a short story about it. The tone should be ${tone}. Keep it concise (under 50 words) suitable for speech.`,
          },
        ],
      },
    });
    return response.text || "Could not describe image.";
  } catch (error) {
    console.error("Error generating text from image:", error);
    throw error;
  }
}

/**
 * Generates audio directly from a provided script using Multi-Speaker TTS.
 * Useful for manual script building.
 */
export const generateDialogueAudio = async (
  script: string,
  speaker1: VoiceName,
  speaker2: VoiceName
): Promise<string> => {
  try {
    const ttsResponse = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: script }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          multiSpeakerVoiceConfig: {
            speakerVoiceConfigs: [
              {
                speaker: speaker1,
                voiceConfig: { prebuiltVoiceConfig: { voiceName: speaker1 } }
              },
              {
                speaker: speaker2,
                voiceConfig: { prebuiltVoiceConfig: { voiceName: speaker2 } }
              }
            ]
          }
        }
      }
    });

    const base64Audio = ttsResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) throw new Error("Failed to generate dialogue audio.");

    return base64Audio;
  } catch (error) {
    console.error("Error generating dialogue audio:", error);
    throw error;
  }
};

/**
 * Generates a Multi-Speaker Audio (Dialogue).
 * 1. Generates the script first using Gemini 3 Flash.
 * 2. Sends script to TTS.
 */
export const generateDialogue = async (
  topic: string, 
  tone: SpeakingTone, 
  speaker1: VoiceName, 
  speaker2: VoiceName
): Promise<{ audio: string; script: string }> => {
  try {
    // Step 1: Generate Script
    const scriptPrompt = `
      Write a short conversation (dialogue) between two people, Speaker A (${speaker1}) and Speaker B (${speaker2}).
      Topic: ${topic}
      Tone: ${tone}
      Length: Short (approx 4-6 exchanges total).
      Format: Return ONLY the dialogue text formatted for TTS. 
      Example:
      ${speaker1}: Hi there!
      ${speaker2}: Hello! How are you?
    `;

    const scriptResponse = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: scriptPrompt,
    });

    const script = scriptResponse.text || "No script generated.";

    // Step 2: Generate Audio
    const audio = await generateDialogueAudio(script, speaker1, speaker2);

    return { audio, script };

  } catch (error) {
    console.error("Error generating dialogue:", error);
    throw error;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { VoiceName, SpeakingTone } from '../types';
import { generateDialogue, generateDialogueAudio } from '../services/geminiService';
import { decode, decodeAudioData } from '../utils/audio';
import { VOICE_META } from '../utils/constants';
import { Play, Square, Loader2, MessageSquareText, User, Wand2, PenTool, Plus, Trash2, ArrowRightLeft } from 'lucide-react';

type BuilderLine = {
    id: number;
    speaker: 'S1' | 'S2';
    text: string;
};

const MagicDialogue: React.FC = () => {
  const [mode, setMode] = useState<'auto' | 'manual'>('auto');

  // Auto Mode State
  const [topic, setTopic] = useState<string>("");
  const [tone, setTone] = useState<SpeakingTone>(SpeakingTone.Normal);

  // Manual Mode State
  const [manualLines, setManualLines] = useState<BuilderLine[]>([
    { id: 1, speaker: 'S1', text: '' },
    { id: 2, speaker: 'S2', text: '' }
  ]);

  // Shared State
  const [script, setScript] = useState<string>("");
  const [speaker1, setSpeaker1] = useState<VoiceName>(VoiceName.Fenrir);
  const [speaker2, setSpeaker2] = useState<VoiceName>(VoiceName.Puck);

  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
      audioContextRef.current = new AudioContextClass({ sampleRate: 24000 });
    }
    return () => audioContextRef.current?.close();
  }, []);

  // Update script preview in manual mode
  useEffect(() => {
    if (mode === 'manual') {
        const previewScript = manualLines
            .filter(l => l.text.trim() !== '')
            .map(l => {
                const name = l.speaker === 'S1' ? speaker1 : speaker2;
                return `${name}: ${l.text}`;
            }).join('\n');
        setScript(previewScript);
    }
  }, [manualLines, speaker1, speaker2, mode]);

  const handleGenerate = async () => {
    setIsLoading(true);
    setError(null);
    stopAudio();

    try {
      let base64Audio = "";

      if (mode === 'auto') {
         if (!topic.trim()) return;
         setScript(""); // Clear previous script
         const result = await generateDialogue(topic, tone, speaker1, speaker2);
         base64Audio = result.audio;
         setScript(result.script);
      } else {
         const formattedScript = manualLines
            .filter(l => l.text.trim() !== '')
            .map(l => {
                const name = l.speaker === 'S1' ? speaker1 : speaker2;
                return `${name}: ${l.text}`;
            }).join('\n');

         if (!formattedScript) throw new Error("Please enter some dialogue text.");

         base64Audio = await generateDialogueAudio(formattedScript, speaker1, speaker2);
      }

      if (!audioContextRef.current) throw new Error("AudioContext not supported");
      if (audioContextRef.current.state === 'suspended') await audioContextRef.current.resume();

      const audioBytes = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioBytes, audioContextRef.current, 24000, 1);

      playBuffer(audioBuffer);

    } catch (err: any) {
      console.error(err);
      setError(err.message || "Failed to generate dialogue.");
    } finally {
      setIsLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    if (!audioContextRef.current) return;
    const source = audioContextRef.current.createBufferSource();
    source.buffer = buffer;
    source.connect(audioContextRef.current.destination);
    source.onended = () => {
      setIsPlaying(false);
      sourceNodeRef.current = null;
    };
    sourceNodeRef.current = source;
    source.start();
    setIsPlaying(true);
  };

  const stopAudio = () => {
    if (sourceNodeRef.current) {
      sourceNodeRef.current.stop();
      sourceNodeRef.current = null;
    }
    setIsPlaying(false);
  };

  // Manual Builder Handlers
  const addLine = () => {
    setManualLines(prev => {
        const lastSpeaker = prev[prev.length - 1]?.speaker;
        return [
            ...prev,
            { id: Date.now(), speaker: lastSpeaker === 'S1' ? 'S2' : 'S1', text: '' }
        ];
    });
  };

  const removeLine = (id: number) => {
    setManualLines(prev => prev.filter(l => l.id !== id));
  };

  const updateLineText = (id: number, text: string) => {
    setManualLines(prev => prev.map(l => l.id === id ? { ...l, text } : l));
  };

  const toggleLineSpeaker = (id: number) => {
    setManualLines(prev => prev.map(l => l.id === id ? { ...l, speaker: l.speaker === 'S1' ? 'S2' : 'S1' } : l));
  };

  const renderSpeakerSelect = (
    label: string, 
