                                <label className="block text-sm font-medium text-slate-300">Dialogue Script</label>
                                <span className="text-xs text-slate-500">Build your conversation line by line</span>
                            </div>

                            <div className="space-y-3 max-h-[400px] overflow-y-auto custom-scrollbar pr-2">
                                {manualLines.map((line, index) => (
                                    <div key={line.id} className="flex gap-2 items-start group">
                                        <button
                                            onClick={() => toggleLineSpeaker(line.id)}
                                            className={`flex-shrink-0 w-20 py-3 rounded-lg flex flex-col items-center justify-center gap-1 transition-all border ${
                                                line.speaker === 'S1' 
                                                    ? 'bg-indigo-900/30 border-indigo-500/50 text-indigo-300 hover:bg-indigo-900/50' 
                                                    : 'bg-purple-900/30 border-purple-500/50 text-purple-300 hover:bg-purple-900/50'
                                            }`}
                                            title="Click to switch speaker"
                                        >
                                            <span className="text-[10px] font-bold uppercase tracking-wider">
                                                {line.speaker === 'S1' ? 'Speaker 1' : 'Speaker 2'}
                                            </span>
                                            <ArrowRightLeft className="w-3 h-3 opacity-50" />
                                        </button>

                                        <textarea
                                            value={line.text}
                                            onChange={(e) => updateLineText(line.id, e.target.value)}
                                            placeholder={`Enter text for ${line.speaker === 'S1' ? 'Speaker 1' : 'Speaker 2'}...`}
                                            className="flex-1 bg-slate-800/50 border border-slate-700 rounded-lg p-3 text-sm text-white placeholder-slate-500 focus:outline-none focus:ring-1 focus:ring-indigo-500 resize-none h-[66px]"
                                        />

                                        <button 
                                            onClick={() => removeLine(line.id)}
                                            className="flex-shrink-0 w-8 h-[66px] flex items-center justify-center text-slate-600 hover:text-red-400 hover:bg-red-900/20 rounded-lg transition-colors"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </div>
                                ))}
                            </div>

                            <button
                                onClick={addLine}
                                className="w-full py-2 border border-dashed border-slate-600 text-slate-400 hover:text-white hover:border-slate-400 hover:bg-slate-800/50 rounded-lg text-sm flex items-center justify-center gap-2 transition-all"
                            >
                                <Plus className="w-4 h-4" /> Add Line
                            </button>
                        </div>
                    )}

                    {/* Action Button */}
                    <div className="pt-2">
                        {!isPlaying ? (
                            <button
                                onClick={handleGenerate}
                                disabled={isLoading || (mode === 'auto' && !topic) || (mode === 'manual' && manualLines.length === 0)}
                                className="w-full py-4 bg-gradient-to-r from-indigo-600 to-purple-600 text-white font-bold rounded-xl shadow-lg shadow-indigo-900/30 flex items-center justify-center gap-2 hover:scale-[1.02] transition-transform disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {isLoading ? <Loader2 className="animate-spin" /> : (mode === 'auto' ? <Wand2 className="w-5 h-5" /> : <Play className="w-5 h-5" />)}
                                <span>{mode === 'auto' ? 'Generate Dialogue' : 'Generate Audio'}</span>
                            </button>
                        ) : (
                            <button onClick={stopAudio} className="w-full py-4 bg-red-500 hover:bg-red-400 text-white font-bold rounded-xl shadow-lg shadow-red-900/30 flex items-center justify-center gap-2 transition-all">
                                <Square className="fill-current" /> Stop Audio
                            </button>
                        )}
                        {error && <div className="mt-4 text-red-400 text-sm bg-red-900/20 p-3 rounded-lg border border-red-800">{error}</div>}
                    </div>
                </div>

                {/* Right Column: Script Display */}
                <div className="bg-slate-950/50 rounded-xl border border-slate-800 p-6 flex flex-col h-[600px] lg:h-auto">
                    <div className="flex items-center justify-between mb-4 sticky top-0 bg-transparent">
                        <h3 className="text-sm font-semibold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                            <MessageSquareText className="w-4 h-4" /> 
                            {mode === 'auto' ? 'Generated Script' : 'Script Preview'}
                        </h3>
                        {script && (
                             <span className="text-[10px] bg-slate-900 px-2 py-1 rounded border border-slate-800 text-slate-500">
                                {script.split('\n').filter(Boolean).length} lines
                             </span>
                        )}
                    </div>

                    <div className="flex-1 overflow-y-auto custom-scrollbar pr-2 space-y-4">
                        {script ? (
                            script.split('\n').map((line, i) => {
                                if (!line.trim()) return null;
                                // Simple check to see if line starts with Speaker 1's name
                                const isSpeaker1 = line.startsWith(speaker1);
                                const speakerName = isSpeaker1 ? speaker1 : speaker2;

                                // Clean up the text for display (remove "Name: " prefix)
                                const displayText = line.replace(`${speakerName}:`, '').trim();

                                return (
                                    <div key={i} className={`flex ${isSpeaker1 ? 'justify-start' : 'justify-end'} animate-in fade-in slide-in-from-bottom-2 duration-500`} style={{animationDelay: `${i * 50}ms`}}>
                                        <div className={`max-w-[85%] p-3 rounded-2xl text-sm relative group ${
                                            isSpeaker1 
                                                ? 'bg-indigo-900/40 text-indigo-100 rounded-tl-none border border-indigo-500/30' 
                                                : 'bg-purple-900/40 text-purple-100 rounded-tr-none border border-purple-500/30'
                                        }`}>
                                            <div className="text-[10px] opacity-60 mb-1 font-bold uppercase tracking-wide flex items-center gap-1">
                                                {isSpeaker1 ? (
                                                    <><span className="w-1.5 h-1.5 rounded-full bg-indigo-400"></span> {speaker1}</>
                                                ) : (
                                                    <><span className="w-1.5 h-1.5 rounded-full bg-purple-400"></span> {speaker2}</>
                                                )}
                                            </div>
                                            <p className="leading-relaxed whitespace-pre-wrap">{displayText}</p>
                                        </div>
                                    </div>
                                )
                            })
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center text-slate-600 opacity-40">
                                <MessageSquareText className="w-16 h-16 mb-4 stroke-1" />
                                <p className="text-sm">
                                    {mode === 'auto' 
                                        ? "Enter a topic and click Generate to see the dialogue script." 
                                        : "Add lines in the builder to preview the script."}
                                </p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    </div>
  );
};

