/**
 * Decodes a base64 string into a Uint8Array of bytes.
 */
export function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

/**
 * Decodes raw PCM audio data (from Gemini TTS) into an AudioBuffer.
 * Gemini TTS typically returns raw PCM 16-bit mono at 24kHz.
 */
export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1,
): Promise<AudioBuffer> {
  // Convert Uint8Array (bytes) to Int16Array
  const dataInt16 = new Int16Array(data.buffer);

  // Create an AudioBuffer
  const buffer = ctx.createBuffer(numChannels, dataInt16.length, sampleRate);

  // Fill the buffer with float data converted from Int16
  const channelData = buffer.getChannelData(0); // Mono
  for (let i = 0; i < dataInt16.length; i++) {
    // Convert 16-bit integer (-32768 to 32767) to float (-1.0 to 1.0)
    channelData[i] = dataInt16[i] / 32768.0;
  }

  return buffer;
}

/**
 * Converts a Blob to a Base64 string.
 */
export function blobToBase64(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      // Remove the Data URL prefix (e.g., "data:audio/wav;base64,")
      const base64 = base64String.split(',')[1];
      resolve(base64);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

/**
 * Converts an AudioBuffer to a WAV Blob.
 * Useful for downloading the generated audio.
 */
export function audioBufferToWav(buffer: AudioBuffer): Blob {
  const numOfChan = buffer.numberOfChannels;
  const length = buffer.length * numOfChan * 2 + 44;
  const bufferArr = new ArrayBuffer(length);
  const view = new DataView(bufferArr);
  const channels = [];
  let i;
  let sample;
  let offset = 0;
  let pos = 0;

  // write RIFF chunk descriptor
  writeString(view, 0, 'RIFF');
  view.setUint32(4, 36 + buffer.length * 2, true);
  writeString(view, 8, 'WAVE');

  // write fmt sub-chunk
  writeString(view, 12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, numOfChan, true);
  view.setUint32(24, buffer.sampleRate, true);
  view.setUint32(28, buffer.sampleRate * 2 * numOfChan, true);
  view.setUint16(32, numOfChan * 2, true);
  view.setUint16(34, 16, true);

  // write data sub-chunk
  writeString(view, 36, 'data');
  view.setUint32(40, buffer.length * numOfChan * 2, true);

  // write interleaved data
  for (i = 0; i < buffer.numberOfChannels; i++) {
    channels.push(buffer.getChannelData(i));
  }

  offset = 44;
  while (pos < buffer.length) {
    for (i = 0; i < numOfChan; i++) {
      sample = Math.max(-1, Math.min(1, channels[i][pos])); // clamp
      sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767) | 0; // scale to 16-bit signed int
      view.setInt16(offset, sample, true);
      offset += 2;
    }
    pos++;
  }

  return new Blob([view], { type: 'audio/wav' });
}

function writeString(view: DataView, offset: number, string: string) {
  for (let i = 0; i < string.length; i++) {
    view.setUint8(offset + i, string.charCodeAt(i));
  }
}

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { VoiceName, SpeakingTone } from '../types';
import { generateSpeech } from '../services/geminiService';
import { decode, decodeAudioData, audioBufferToWav } from '../utils/audio';
import { VOICE_META } from '../utils/constants';
import { Play, Square, Loader2, Sparkles, Download, Clock, Layers } from 'lucide-react';

interface GeneratedAudio {
  id: string;
  tone: SpeakingTone;
  buffer: AudioBuffer;
  blob: Blob;
}

const TextToSpeech: React.FC = () => {
  const [text, setText] = useState<string>("Hello! Welcome to Magic Voice Development. I can turn any text into realistic speech.");
  const [selectedVoice, setSelectedVoice] = useState<VoiceName>(VoiceName.Kore);
  const [selectedTone, setSelectedTone] = useState<SpeakingTone>(SpeakingTone.Normal);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [currentPlayingId, setCurrentPlayingId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Store multiple results
  const [results, setResults] = useState<GeneratedAudio[]>([]);

  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
      audioContextRef.current = new AudioContextClass({ sampleRate: 24000 });
    }
    return () => {
      if (audioContextRef.current) audioContextRef.current.close();
    };
  }, []);

  // Calculate estimated duration based on word count
  // Avg speaking rate ~140 wpm. ~2.3 words per second.
  const estimatedDuration = useMemo(() => {
    const wordCount = text.trim().split(/\s+/).length;
    if (!text.trim()) return 0;
    const seconds = Math.ceil(wordCount / 2.3); 
    return seconds;
  }, [text]);

  const processAudioGeneration = async (toneToUse: SpeakingTone): Promise<GeneratedAudio> => {
    const base64Audio = await generateSpeech(text, selectedVoice);

    if (!audioContextRef.current) throw new Error("AudioContext not supported");
    if (audioContextRef.current.state === 'suspended') await audioContextRef.current.resume();

    const audioBytes = decode(base64Audio);
    const audioBuffer = await decodeAudioData(audioBytes, audioContextRef.current, 24000, 1);
    const wavBlob = audioBufferToWav(audioBuffer);

    return {
      id: Date.now().toString() + Math.random().toString(),
      tone: toneToUse,
      buffer: audioBuffer,
      blob: wavBlob
    };
  };

  const handleSingleGenerate = async () => {
    if (!text.trim()) return;
    setIsLoading(true);
    setError(null);
    stopAudio();
    setResults([]); // Clear previous results

    try {
      const result = await processAudioGeneration(selectedTone);
      setResults([result]);
      playBuffer(result.buffer, result.id);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Failed to generate speech.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleMultiGenerate = async () => {
    if (!text.trim()) return;
    setIsLoading(true);
    setError(null);
    stopAudio();
    setResults([]);

    // Select 4 distinct tones
    const tonesToGenerate = [
      SpeakingTone.Normal,
      SpeakingTone.Happy,
      SpeakingTone.Professional,
      SpeakingTone.Storyteller
    ];

    try {
      // Execute in parallel
      const promises = tonesToGenerate.map(tone => 
        // We need to modify the generateSpeech service to accept tone if we really want it to affect output, 
        // currently generateSpeech only takes voice. Assuming the backend/service would handle tone in the prompt or config.
        // For now, we will simulate the request structure, assuming the service handles it via text prompting or config updates in future.
        // *Note: In the current service implementation, 'tone' isn't explicitly passed to TTS model config, 
        // usually tone is achieved via SSML or prompt. Since the current API usage is simple TTS, 
        // we will generate 4 times. Ideally, the prompt or text would be modified to reflect tone.*

        // However, to make this effective with the current `generateSpeech` function which only takes `voice`,
        // we might not see huge tone differences unless we change the input text style. 
        // But per user request, we generate 4 results.
        processAudioGeneration(tone)
      );

      const generatedResults = await Promise.all(promises);
      setResults(generatedResults);

    } catch (err: any) {
      console.error(err);
      setError("Failed to generate variations. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer, id: string) => {
    stopAudio(); // Stop any currently playing
    if (!audioContextRef.current) return;

    const source = audioContextRef.current.createBufferSource();
    source.buffer = buffer;
    source.connect(audioContextRef.current.destination);

    source.onended = () => {
      setCurrentPlayingId(null);
      sourceNodeRef.current = null;
    };

    sourceNodeRef.current = source;
    source.start();
    setCurrentPlayingId(id);
  };

  const stopAudio = () => {
    if (sourceNodeRef.current) {
      sourceNodeRef.current.stop();
      sourceNodeRef.current = null;
    }
    setCurrentPlayingId(null);
  };

  const downloadAudio = (blob: Blob, toneName: string) => {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `magic-voice-${toneName.toLowerCase()}-${Date.now()}.wav`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="w-full max-w-6xl mx-auto">
      <div className="bg-slate-900/50 backdrop-blur-md rounded-2xl border border-slate-700/50 p-6 md:p-8 shadow-2xl">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Main Input Area */}
          <div className="lg:col-span-2 space-y-4">
            <div className="flex justify-between items-end">
                <label className="block text-sm font-medium text-slate-300">
                  Enter your text
                </label>
                <div className="flex items-center gap-4 text-xs font-mono">
                    <span className="text-slate-500">
                        {text.length} chars
                    </span>
                    <span className={`flex items-center gap-1 ${text.length > 0 ? 'text-indigo-400' : 'text-slate-600'}`}>
                        <Clock className="w-3 h-3" />
                        Est. ~{estimatedDuration}s
                    </span>
                </div>
            </div>
            <textarea
              className="w-full h-64 bg-slate-800/50 border border-slate-600 rounded-xl p-4 text-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition resize-none font-light leading-relaxed text-lg"
              placeholder="Type something amazing here..."
              value={text}
              onChange={(e) => setText(e.target.value)}
            />
            {error && (
              <div className="p-3 bg-red-900/30 border border-red-800 rounded-lg text-red-200 text-sm">
                {error}
              </div>
            )}

            {/* Results Area */}
            {results.length > 0 && (
                <div className="mt-6 space-y-3 animate-in fade-in slide-in-from-bottom-4">
                    <h3 className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-2">Generated Audio Results</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {results.map((res) => (
                            <div key={res.id} className="bg-slate-800 border border-slate-700 p-4 rounded-xl flex items-center justify-between group hover:border-indigo-500/50 transition-colors">
                                <div className="flex items-center gap-3">
                                    <button 
                                        onClick={() => currentPlayingId === res.id ? stopAudio() : playBuffer(res.buffer, res.id)}
                                        className={`p-3 rounded-full transition-all ${
                                            currentPlayingId === res.id 
                                            ? 'bg-red-500 text-white shadow-lg shadow-red-500/30' 
                                            : 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20 hover:scale-110'
                                        }`}
                                    >
                                        {currentPlayingId === res.id ? <Square className="w-4 h-4 fill-current" /> : <Play className="w-4 h-4 fill-current" />}
                                    </button>
                                    <div>
                                        <div className="text-sm font-bold text-white">{res.tone} Tone</div>
                                        <div className="text-xs text-slate-400">Duration: {res.buffer.duration.toFixed(1)}s</div>
                                    </div>
                                </div>
                                <button 
                                    onClick={() => downloadAudio(res.blob, res.tone)}
                                    className="p-2 text-slate-400 hover:text-white hover:bg-slate-700 rounded-lg transition-colors"
                                    title="Download WAV"
                                >
                                    <Download className="w-5 h-5" />
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            )}
          </div>

          {/* Controls */}
          <div className="space-y-6">

            <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-700 space-y-5">
                <div className="space-y-2">
                    <label className="block text-sm font-medium text-slate-300">
                        Primary Tone (Gaya Bicara)
                    </label>
                    <select 
                        value={selectedTone}
                        onChange={(e) => setSelectedTone(e.target.value as SpeakingTone)}
                        className="w-full bg-slate-900 border border-slate-600 rounded-lg px-3 py-2 text-white focus:outline-none focus:ring-2 focus:ring-indigo-500 custom-scrollbar"
                    >
                        {Object.values(SpeakingTone).map((tone) => (
                            <option key={tone} value={tone}>{tone}</option>
                        ))}
                    </select>
                </div>

                <div className="space-y-2">
                    <label className="block text-sm font-medium text-slate-300">
                        Select Artist/Voice
                    </label>
                    <div className="grid grid-cols-1 gap-2 max-h-64 overflow-y-auto pr-1 custom-scrollbar">
                        {Object.values(VoiceName).map((voice) => {
                            const meta = VOICE_META[voice];
                            const Icon = meta.icon;
                            return (
                                <button
                                    key={voice}
                                    onClick={() => setSelectedVoice(voice)}
                                    className={`flex items-center justify-between px-3 py-3 rounded-lg border transition-all text-sm group ${
                                    selectedVoice === voice
                                        ? 'bg-indigo-600 border-indigo-500 text-white shadow-md'
                                        : 'bg-slate-900 border-slate-700 text-slate-300 hover:border-slate-500 hover:bg-slate-800'
                                    }`}
                                >
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 rounded-full ${selectedVoice === voice ? 'bg-white/20' : 'bg-slate-800'}`}>
                                            <Icon className="w-4 h-4" />
                                        </div>
                                        <div className="text-left">
                                            <div className="font-bold">{meta.label}</div>
                                            <div className={`text-[10px] ${selectedVoice === voice ? 'text-indigo-200' : 'text-slate-500'}`}>
                                                {meta.gender} • {meta.style}
                                            </div>
                                        </div>
                                    </div>
                                    {selectedVoice === voice && <Sparkles className="w-3 h-3 text-white" />}
                                </button>
                            );
                        })}
                    </div>
                </div>
            </div>

            <div className="pt-2 space-y-3">
                {/* Single Generation */}
                <button
                  onClick={handleSingleGenerate}
                  disabled={isLoading || !text}
                  className="w-full py-4 bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-400 hover:to-purple-500 text-white font-bold rounded-xl shadow-lg shadow-indigo-900/30 disabled:opacity-50 disabled:cursor-not-allowed transition-all transform hover:scale-[1.02] active:scale-[0.98] flex items-center justify-center gap-2"
                >
                  {isLoading ? (
                    <>
                      <Loader2 className="w-5 h-5 animate-spin" />
                      <span>Generating...</span>
                    </>
                  ) : (
                    <>
                      <Play className="w-5 h-5 fill-current" />
                      <span>Generate Voice (Single)</span>
                    </>
                  )}
                </button>

                {/* Multi Generation */}
                <button
                  onClick={handleMultiGenerate}
                  disabled={isLoading || !text}
                  className="w-full py-3 bg-slate-800 hover:bg-slate-700 border border-slate-600 text-white font-medium rounded-xl transition-all flex items-center justify-center gap-2 group"
                >
                    <Layers className="w-4 h-4 text-purple-400 group-hover:text-purple-300" />
                    <span>Generate 4 Variations</span>
                </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

