import React, { useState, useRef, useEffect } from 'react';
import { VoiceName, SpeakingTone } from '../types';
import { generateDialogue, generateDialogueAudio } from '../services/geminiService';
import { decode, decodeAudioData, audioBufferToWav } from '../utils/audio';
import { VOICE_META } from '../utils/constants';
import { Play, Square, Loader2, MessageSquareText, User, Wand2, PenTool, Plus, Trash2, ArrowRightLeft, Download } from 'lucide-react';

type BuilderLine = {
    id: number;
    speaker: 'S1' | 'S2';
    text: string;
};

const MagicDialogue: React.FC = () => {
  const [mode, setMode] = useState<'auto' | 'manual'>('auto');

  // Auto Mode State
  const [topic, setTopic] = useState<string>("");
  const [tone, setTone] = useState<SpeakingTone>(SpeakingTone.Normal);

  // Manual Mode State
  const [manualLines, setManualLines] = useState<BuilderLine[]>([
    { id: 1, speaker: 'S1', text: '' },
    { id: 2, speaker: 'S2', text: '' }
  ]);

  // Shared State
  const [script, setScript] = useState<string>("");
  const [speaker1, setSpeaker1] = useState<VoiceName>(VoiceName.Fenrir);
  const [speaker2, setSpeaker2] = useState<VoiceName>(VoiceName.Puck);

  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  // Audio Download State
  const [currentAudioBlob, setCurrentAudioBlob] = useState<Blob | null>(null);

  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
      audioContextRef.current = new AudioContextClass({ sampleRate: 24000 });
    }
    return () => audioContextRef.current?.close();
  }, []);

  // Update script preview in manual mode
  useEffect(() => {
    if (mode === 'manual') {
        const previewScript = manualLines
            .filter(l => l.text.trim() !== '')
            .map(l => {
                const name = l.speaker === 'S1' ? speaker1 : speaker2;
                return `${name}: ${l.text}`;
            }).join('\n');
        setScript(previewScript);
    }
  }, [manualLines, speaker1, speaker2, mode]);

  const handleGenerate = async () => {
    setIsLoading(true);
    setError(null);
    setCurrentAudioBlob(null);
    stopAudio();

    try {
      let base64Audio = "";

      if (mode === 'auto') {
         if (!topic.trim()) return;
         setScript(""); // Clear previous script
         const result = await generateDialogue(topic, tone, speaker1, speaker2);
         base64Audio = result.audio;
         setScript(result.script);
      } else {
         const formattedScript = manualLines
            .filter(l => l.text.trim() !== '')
            .map(l => {
                const name = l.speaker === 'S1' ? speaker1 : speaker2;
                return `${name}: ${l.text}`;
            }).join('\n');

         if (!formattedScript) throw new Error("Please enter some dialogue text.");

         base64Audio = await generateDialogueAudio(formattedScript, speaker1, speaker2);
      }

      if (!audioContextRef.current) throw new Error("AudioContext not supported");
      if (audioContextRef.current.state === 'suspended') await audioContextRef.current.resume();

      const audioBytes = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioBytes, audioContextRef.current, 24000, 1);

      // Create Wav Blob for download
      const wavBlob = audioBufferToWav(audioBuffer);
      setCurrentAudioBlob(wavBlob);

      playBuffer(audioBuffer);

    } catch (err: any) {
      console.error(err);
      setError(err.message || "Failed to generate dialogue.");
    } finally {
      setIsLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    if (!audioContextRef.current) return;
    const source = audioContextRef.current.createBufferSource();
    source.buffer = buffer;
    source.connect(audioContextRef.current.destination);
    source.onended = () => {
      setIsPlaying(false);
      sourceNodeRef.current = null;
    };
    sourceNodeRef.current = source;
    source.start();
    setIsPlaying(true);
  };

  const stopAudio = () => {
    if (sourceNodeRef.current) {
      sourceNodeRef.current.stop();
      sourceNodeRef.current = null;
    }
    setIsPlaying(false);
  };

  const downloadAudio = () => {
    if (!currentAudioBlob) return;
    const url = URL.createObjectURL(currentAudioBlob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `magic-dialogue-${Date.now()}.wav`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  // Manual Builder Handlers
  const addLine = () => {
    setManualLines(prev => {
        const lastSpeaker = prev[prev.length - 1]?.speaker;
        return [
            ...prev,
            { id: Date.now(), speaker: lastSpeaker === 'S1' ? 'S2' : 'S1', text: '' }
        ];
    });
  };

  const removeLine = (id: number) => {
    setManualLines(prev => prev.filter(l => l.id !== id));
  };

  const updateLineText = (id: number, text: string) => {
    setManualLines(prev => prev.map(l => l.id === id ? { ...l, text } : l));
  };

  const toggleLineSpeaker = (id: number) => {
    setManualLines(prev => prev.map(l => l.id === id ? { ...l, speaker: l.speaker === 'S1' ? 'S2' : 'S1' } : l));
  };

  const renderSpeakerSelect = (
    label: string, 
    value: VoiceName, 
    onChange: (val: VoiceName) => void,
    colorClass: string
  ) => {
    const meta = VOICE_META[value];
    const Icon = meta.icon;

    return (
        <div className="space-y-2">
            <label className={`block text-xs font-bold uppercase tracking-wider mb-2 flex items-center gap-1 ${colorClass}`}>
                <User className="w-3 h-3" /> {label}
            </label>
            <div className="relative group">
                <select 
                    value={value}
                    onChange={(e) => onChange(e.target.value as VoiceName)}
                    className="w-full bg-slate-800 border border-slate-600 rounded-lg pl-3 pr-10 py-3 text-white appearance-none focus:ring-2 focus:ring-indigo-500 outline-none"
                >
                    {Object.values(VoiceName).map(v => (
                        <option key={v} value={v}>
                            {VOICE_META[v].label} ({VOICE_META[v].gender})
                        </option>
                    ))}
                </select>
                <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none">
                    <Icon className="w-4 h-4 text-slate-400" />
                </div>
            </div>
            <p className="text-[10px] text-slate-500">
                {meta.style}
            </p>
        </div>
    );
  };

  return (
    <div className="w-full max-w-6xl mx-auto">
        <div className="bg-slate-900/50 backdrop-blur-md rounded-2xl border border-slate-700/50 p-6 md:p-8 shadow-2xl">

            <div className="flex justify-center mb-8">
                <div className="bg-slate-950 p-1 rounded-xl border border-slate-800 flex gap-1">
                    <button
                        onClick={() => setMode('auto')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition-all ${
                            mode === 'auto' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'
                        }`}
                    >
                        <Wand2 className="w-4 h-4" /> AI Generator
                    </button>
                    <button
                        onClick={() => setMode('manual')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition-all ${
                            mode === 'manual' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'
                        }`}
                    >
                        <PenTool className="w-4 h-4" /> Script Builder
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
                {/* Left Column: Configuration & Inputs */}
                <div className="space-y-6">

                    {/* Speaker Configuration (Always Visible) */}
                    <div className="grid grid-cols-2 gap-4 bg-slate-950/30 p-4 rounded-xl border border-slate-800">
                        {renderSpeakerSelect("Speaker 1", speaker1, setSpeaker1, "text-indigo-400")}
                        {renderSpeakerSelect("Speaker 2", speaker2, setSpeaker2, "text-purple-400")}
                    </div>

                    {mode === 'auto' ? (
                        /* AUTO MODE INPUTS */
                        <div className="space-y-6 animate-in fade-in slide-in-from-left-4 duration-300">
                            <div>
                                <label className="block text-sm font-medium text-slate-300 mb-2">Conversation Topic</label>
                                <textarea
                                    value={topic}
                                    onChange={(e) => setTopic(e.target.value)}
                                    placeholder="e.g. Discussing the best pizza toppings..."
                                    className="w-full h-32 bg-slate-800/50 border border-slate-600 rounded-xl p-4 text-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-slate-300 mb-2">Conversation Tone</label>
                                <select 
                                    value={tone}
                                    onChange={(e) => setTone(e.target.value as SpeakingTone)}
                                    className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-3 text-white focus:outline-none focus:ring-2 focus:ring-indigo-500"
                                >
                                    {Object.values(SpeakingTone).map(t => <option key={t} value={t}>{t}</option>)}
                                </select>
                            </div>
                        </div>
                    ) : (
                        /* MANUAL MODE INPUTS */
                        <div className="space-y-4 animate-in fade-in slide-in-from-right-4 duration-300">
                            <div className="flex items-center justify-between">
                                <label className="block text-sm font-medium text-slate-300">Dialogue Script</label>
                                <span className="text-xs text-slate-500">Build your conversation line by line</span>
                            </div>

                            <div className="space-y-3 max-h-[400px] overflow-y-auto custom-scrollbar pr-2">
                                {manualLines.map((line, index) => (
                                    <div key={line.id} className="flex gap-2 items-start group">
                                        <button
                                            onClick={() => toggleLineSpeaker(line.id)}
                                            className={`flex-shrink-0 w-20 py-3 rounded-lg flex flex-col items-center justify-center gap-1 transition-all border ${
                                                line.speaker === 'S1' 
                                                    ? 'bg-indigo-900/30 border-indigo-500/50 text-indigo-300 hover:bg-indigo-900/50' 
                                                    : 'bg-purple-900/30 border-purple-500/50 text-purple-300 hover:bg-purple-900/50'
                                            }`}
                                            title="Click to switch speaker"
                                        >
                                            <span className="text-[10px] font-bold uppercase tracking-wider">
                                                {line.speaker === 'S1' ? 'Speaker 1' : 'Speaker 2'}
                                            </span>
                                            <ArrowRightLeft className="w-3 h-3 opacity-50" />
                                        </button>

                                        <textarea
                                            value={line.text}
                                            onChange={(e) => updateLineText(line.id, e.target.value)}
                                            placeholder={`Enter text for ${line.speaker === 'S1' ? 'Speaker 1' : 'Speaker 2'}...`}
                                            className="flex-1 bg-slate-800/50 border border-slate-700 rounded-lg p-3 text-sm text-white placeholder-slate-500 focus:outline-none focus:ring-1 focus:ring-indigo-500 resize-none h-[66px]"
                                        />

                                        <button 
                                            onClick={() => removeLine(line.id)}
                                            className="flex-shrink-0 w-8 h-[66px] flex items-center justify-center text-slate-600 hover:text-red-400 hover:bg-red-900/20 rounded-lg transition-colors"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </div>
                                ))}
                            </div>

                            <button
                                onClick={addLine}
                                className="w-full py-2 border border-dashed border-slate-600 text-slate-400 hover:text-white hover:border-slate-400 hover:bg-slate-800/50 rounded-lg text-sm flex items-center justify-center gap-2 transition-all"
                            >
                                <Plus className="w-4 h-4" /> Add Line
                            </button>
                        </div>
                    )}

                    {/* Action Button */}
                    <div className="pt-2 flex flex-col gap-3">
                        {!isPlaying ? (
                            <button
                                onClick={handleGenerate}
                                disabled={isLoading || (mode === 'auto' && !topic) || (mode === 'manual' && manualLines.length === 0)}
                                className="w-full py-4 bg-gradient-to-r from-indigo-600 to-purple-600 text-white font-bold rounded-xl shadow-lg shadow-indigo-900/30 flex items-center justify-center gap-2 hover:scale-[1.02] transition-transform disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {isLoading ? <Loader2 className="animate-spin" /> : (mode === 'auto' ? <Wand2 className="w-5 h-5" /> : <Play className="w-5 h-5" />)}
                                <span>{mode === 'auto' ? 'Generate Dialogue' : 'Generate Audio'}</span>
                            </button>
                        ) : (
                            <button onClick={stopAudio} className="w-full py-4 bg-red-500 hover:bg-red-400 text-white font-bold rounded-xl shadow-lg shadow-red-900/30 flex items-center justify-center gap-2 transition-all">
                                <Square className="fill-current" /> Stop Audio
                            </button>
                        )}

                        {currentAudioBlob && (
                             <button
                                onClick={downloadAudio}
                                className="w-full py-3 bg-slate-800 hover:bg-slate-700 border border-slate-600 text-white font-medium rounded-xl flex items-center justify-center gap-2 transition-all"
                            >
                                <Download className="w-4 h-4" /> Download WAV
                            </button>
                        )}

                        {error && <div className="mt-4 text-red-400 text-sm bg-red-900/20 p-3 rounded-lg border border-red-800">{error}</div>}
                    </div>
                </div>

                {/* Right Column: Script Display */}
                <div className="bg-slate-950/50 rounded-xl border border-slate-800 p-6 flex flex-col h-[600px] lg:h-auto">
                    <div className="flex items-center justify-between mb-4 sticky top-0 bg-transparent">
                        <h3 className="text-sm font-semibold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                            <MessageSquareText className="w-4 h-4" /> 
                            {mode === 'auto' ? 'Generated Script' : 'Script Preview'}
                        </h3>
                        {script && (
                             <span className="text-[10px] bg-slate-900 px-2 py-1 rounded border border-slate-800 text-slate-500">
                                {script.split('\n').filter(Boolean).length} lines
                             </span>
                        )}
                    </div>

                    <div className="flex-1 overflow-y-auto custom-scrollbar pr-2 space-y-4">
                        {script ? (
                            script.split('\n').map((line, i) => {
                                if (!line.trim()) return null;
                                // Simple check to see if line starts with Speaker 1's name
                                const isSpeaker1 = line.startsWith(speaker1);
                                const speakerName = isSpeaker1 ? speaker1 : speaker2;

                                // Clean up the text for display (remove "Name: " prefix)
                                const displayText = line.replace(`${speakerName}:`, '').trim();

                                return (
                                    <div key={i} className={`flex ${isSpeaker1 ? 'justify-start' : 'justify-end'} animate-in fade-in slide-in-from-bottom-2 duration-500`} style={{animationDelay: `${i * 50}ms`}}>
                                        <div className={`max-w-[85%] p-3 rounded-2xl text-sm relative group ${
                                            isSpeaker1 
                                                ? 'bg-indigo-900/40 text-indigo-100 rounded-tl-none border border-indigo-500/30' 
                                                : 'bg-purple-900/40 text-purple-100 rounded-tr-none border border-purple-500/30'
                                        }`}>
                                            <div className="text-[10px] opacity-60 mb-1 font-bold uppercase tracking-wide flex items-center gap-1">
                                                {isSpeaker1 ? (
                                                    <><span className="w-1.5 h-1.5 rounded-full bg-indigo-400"></span> {speaker1}</>
                                                ) : (
                                                    <><span className="w-1.5 h-1.5 rounded-full bg-purple-400"></span> {speaker2}</>
                                                )}
                                            </div>
                                            <p className="leading-relaxed whitespace-pre-wrap">{displayText}</p>
                                        </div>
                                    </div>
                                )
                            })
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center text-slate-600 opacity-40">
                                <MessageSquareText className="w-16 h-16 mb-4 stroke-1" />
                                <p className="text-sm">
                                    {mode === 'auto' 
                                        ? "Enter a topic and click Generate to see the dialogue script." 
                                        : "Add lines in the builder to preview the script."}
                                </p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    </div>
  );
};

